//! Seeded key sampling, commit-gated key allocation, and verifiable binary values.

use std::{
    alloc::System,
    fs::File,
    ops::{Range, RangeInclusive},
    path::{Path, PathBuf},
    sync::{
        atomic::{AtomicU64, Ordering},
        Mutex,
    },
};

use memmap2::Mmap;
use serde::Serialize;

use crate::backend::{Key, KeyType, KeyWidth};

/// How record ordinals become keys: generated by a [`KeyType`], or read from a sorted key file.
pub enum Keys {
    Generated(KeyType),
    Mapped(KeyShards),
}

impl Keys {
    /// Keys from the `.i32bin`, `.u64bin` or `.uuidbin` shards `pattern` names, or generated by `key_type`.
    pub fn new(pattern: Option<&Path>, key_type: KeyType) -> Result<Self, String> {
        match pattern {
            Some(pattern) => KeyShards::load(pattern).map(Self::Mapped),
            None => Ok(Self::Generated(key_type)),
        }
    }

    /// The key of record `ordinal`, unique to it.
    pub fn encode(&self, ordinal: u64) -> Key {
        match self {
            Self::Generated(key_type) => key_type.encode(ordinal),
            Self::Mapped(shards) => shards.get(ordinal),
        }
    }

    /// The ordinal [`encode`](Self::encode) made `key` from, or `None` for a key it never makes.
    pub fn decode(&self, key: Key) -> Option<u64> {
        match self {
            Self::Generated(key_type) => key_type.decode(key),
            Self::Mapped(shards) => shards.find(key),
        }
    }

    /// Ordinals these keys can name before they run out.
    pub fn capacity(&self) -> u64 {
        match self {
            Self::Generated(key_type) => key_type.capacity(),
            Self::Mapped(shards) => shards.rows(),
        }
    }
}

/// Bytes of the `rows: u32, width: u32` header each key shard opens with.
const SHARD_HEADER_BYTES: usize = 8;

/// Memory-mapped key shards holding ascending, unique keys, so a key's ordinal is a binary search
/// away and keeps no memory per key.
pub struct KeyShards {
    mmaps: Vec<Mmap, System>,
    /// `offsets[i]` keys live in shards `0..i`; the last entry is the total.
    offsets: Vec<u64, System>,
    width: KeyWidth,
}

impl KeyShards {
    /// Maps every shard `pattern` names, in natural order, and checks that keys ascend across them.
    pub fn load(pattern: &Path) -> Result<Self, String> {
        let width = KeyWidth::of_file(pattern)?;
        let mut mmaps = Vec::new_in(System);
        let mut offsets = Vec::new_in(System);
        offsets.push(0);
        for path in expand_glob(pattern)? {
            let failed = |error: std::io::Error| format!("{}: {error}", path.display());
            // SAFETY: key files are read-only inputs nothing writes during a run.
            let mmap = unsafe { Mmap::map(&File::open(&path).map_err(failed)?) }.map_err(failed)?;
            let header = mmap
                .get(..SHARD_HEADER_BYTES)
                .ok_or_else(|| format!("{}: no header", path.display()))?;
            let rows = u64::from(u32::from_le_bytes(header[..4].try_into().unwrap()));
            if (mmap.len() - SHARD_HEADER_BYTES) as u64 != rows * width.size() as u64 {
                return Err(format!("{}: {rows} keys do not fill the file", path.display()));
            }
            offsets.push(offsets.last().unwrap() + rows);
            mmaps.push(mmap);
        }
        let shards = Self { mmaps, offsets, width };
        if (1..shards.rows()).any(|row| shards.get(row - 1) >= shards.get(row)) {
            return Err(format!("{}: keys must ascend without repeats", pattern.display()));
        }
        Ok(shards)
    }

    pub fn rows(&self) -> u64 {
        *self.offsets.last().unwrap()
    }

    pub fn get(&self, row: u64) -> Key {
        // `partition_point` counts the offsets at or below `row`, one past the shard holding it.
        let shard = self.offsets.partition_point(|&offset| offset <= row) - 1;
        let start = SHARD_HEADER_BYTES + (row - self.offsets[shard]) as usize * self.width.size();
        self.width.read(&self.mmaps[shard][start..start + self.width.size()])
    }

    /// The row holding `key`, by binary search over the ascending keys.
    fn find(&self, key: Key) -> Option<u64> {
        let (mut low, mut high) = (0, self.rows());
        while low < high {
            let middle = low + (high - low) / 2;
            match self.get(middle) < key {
                true => low = middle + 1,
                false => high = middle,
            }
        }
        (low < self.rows() && self.get(low) == key).then_some(low)
    }
}

/// One run of a natural-sort key: text sorts before numbers, so `keys.u64bin` precedes
/// `keys.part_0.u64bin`, and numbers compare by value, so `part_2` precedes `part_10`.
#[derive(Debug, Eq, PartialEq, Ord, PartialOrd)]
enum NaturalSegment<'a> {
    Text(&'a [u8]),
    Number(u64),
}

fn natural_key(name: &str) -> Vec<NaturalSegment<'_>, System> {
    let bytes = name.as_bytes();
    let mut segments = Vec::new_in(System);
    let mut position = 0;
    while position < bytes.len() {
        let start = position;
        let digits = bytes[start].is_ascii_digit();
        while position < bytes.len() && bytes[position].is_ascii_digit() == digits {
            position += 1;
        }
        let run = &bytes[start..position];
        segments.push(match digits {
            true => NaturalSegment::Number(run.iter().fold(0u64, |number, &digit| {
                number.saturating_mul(10).saturating_add(u64::from(digit - b'0'))
            })),
            false => NaturalSegment::Text(run),
        });
    }
    segments
}

/// The files `pattern` names, naturally sorted; a pattern without `*`, `?` or `[` is one path.
fn expand_glob(pattern: &Path) -> Result<Vec<PathBuf, System>, String> {
    let mut paths = Vec::new_in(System);
    let text = pattern.to_string_lossy();
    if !text.contains(['*', '?', '[']) {
        paths.push(pattern.to_path_buf());
        return Ok(paths);
    }
    for entry in glob::glob(&text).map_err(|error| format!("glob({text}): {error}"))? {
        paths.push(entry.map_err(|error| format!("glob({text}): {error}"))?);
    }
    if paths.is_empty() {
        return Err(format!("glob({text}) matched no files"));
    }
    paths.sort_by(|left, right| natural_key(&left.to_string_lossy()).cmp(&natural_key(&right.to_string_lossy())));
    Ok(paths)
}

#[derive(Clone, Copy, Debug, PartialEq, Eq, clap::ValueEnum, Serialize)]
#[serde(rename_all = "kebab-case")]
pub enum Distribution {
    Uniform,
    Zipf,
    Latest,
}

pub struct RandomGenerator {
    state: u64,
    latest: (u64, f64, f64),
}

impl RandomGenerator {
    pub fn new(seed: u64) -> Self {
        Self {
            state: seed,
            latest: (0, 0.0, 0.0),
        }
    }
    pub fn next_u64(&mut self) -> u64 {
        self.state = self.state.wrapping_add(0xa0761d6478bd642f);
        let product = (self.state as u128) * ((self.state ^ 0xe7037ed1a0b428db) as u128);
        product as u64 ^ (product >> 64) as u64
    }
    pub fn below(&mut self, bound: u64) -> u64 {
        assert!(bound > 0);
        let threshold = bound.wrapping_neg() % bound;
        loop {
            let value = self.next_u64();
            if value >= threshold {
                return value % bound;
            }
        }
    }
    pub fn sample(&mut self, distribution: Distribution, live: Range<u64>) -> Option<u64> {
        let count = live.end.checked_sub(live.start)?;
        if count == 0 {
            return None;
        }
        let offset = match distribution {
            Distribution::Uniform => self.below(count),
            Distribution::Zipf => {
                let rank = self.zipf_rank(
                    10_000_000_000,
                    26.46902820178302,
                    zipf_eta(10_000_000_000, 26.46902820178302),
                );
                fnv(&rank.to_le_bytes()) % count
            }
            Distribution::Latest => {
                if count == 1 {
                    return Some(live.start);
                }
                if self.latest.0 != count {
                    let zeta = zeta(count);
                    self.latest = (count, zeta, zipf_eta(count, zeta));
                }
                count - 1 - self.zipf_rank(count, self.latest.1, self.latest.2)
            }
        };
        Some(live.start + offset)
    }
    fn zipf_rank(&mut self, count: u64, zeta: f64, eta: f64) -> u64 {
        let u = (self.next_u64() >> 11) as f64 * (1.0 / ((1u64 << 53) as f64));
        let uz = u * zeta;
        if uz < 1.0 {
            0
        } else if uz < 1.0 + 0.5_f64.powf(0.99) {
            1.min(count - 1)
        } else {
            ((count as f64 * (eta * u - eta + 1.0).powf(100.0)) as u64).min(count - 1)
        }
    }
}

fn zipf_eta(count: u64, zeta: f64) -> f64 {
    (1.0 - (2.0 / count as f64).powf(0.01)) / (1.0 - (1.0 + 0.5_f64.powf(0.99)) / zeta)
}

fn zeta(count: u64) -> f64 {
    let exact = count.min(128);
    let mut sum = (1..=exact).map(|i| (i as f64).powf(-0.99)).sum::<f64>();
    if count > exact {
        // Euler–Maclaurin avoids walking a billion-item keyspace when its size changes.
        let a = exact as f64;
        let b = count as f64;
        sum += (b.powf(0.01) - a.powf(0.01)) / 0.01
            + (b.powf(-0.99) - a.powf(-0.99)) / 2.0
            + 0.99 * (a.powf(-1.99) - b.powf(-1.99)) / 12.0;
    }
    sum
}

fn fnv(bytes: &[u8]) -> u64 {
    bytes.iter().fold(0xcbf29ce484222325, |hash, byte| {
        (hash ^ u64::from(*byte)).wrapping_mul(1099511628211)
    })
}

pub fn derive_seed(seed: u64, workload: &str, thread: usize) -> u64 {
    fnv(workload.as_bytes()) ^ fnv(&seed.to_le_bytes()) ^ fnv(&(thread as u64).to_le_bytes()).rotate_left(23)
}

struct Reservations {
    next: u64,
    pending: Vec<Option<u64>, System>,
}

/// Published keys include only contiguous, successfully committed insert reservations.
pub struct KeySpace {
    floor: AtomicU64,
    acknowledged: AtomicU64,
    reservations: Mutex<Reservations>,
}

impl KeySpace {
    pub fn new(initial: u64) -> Self {
        Self {
            floor: AtomicU64::new(0),
            acknowledged: AtomicU64::new(initial),
            reservations: Mutex::new(Reservations {
                next: initial,
                pending: Vec::new_in(System),
            }),
        }
    }
    pub fn restore(live: Range<u64>) -> Result<Self, String> {
        if live.start > live.end {
            return Err("invalid persisted key range".into());
        }
        let keys = Self::new(live.end);
        keys.floor.store(live.start, Ordering::Relaxed);
        Ok(keys)
    }
    pub fn live(&self) -> Range<u64> {
        let end = self.acknowledged.load(Ordering::Acquire);
        self.floor.load(Ordering::Acquire).min(end)..end
    }
    pub fn workers(&self, count: usize) {
        let mut state = self.reservations.lock().unwrap();
        assert!(state.pending.iter().all(Option::is_none));
        state.pending.clear();
        state.pending.resize(count, None);
    }
    pub fn reserve(&self, worker: usize, count: u64) -> Result<Range<u64>, String> {
        let mut state = self.reservations.lock().unwrap();
        let start = state.next;
        let end = start.checked_add(count).ok_or("key space exhausted")?;
        if count != 0 {
            if state.pending[worker].is_none() {
                state.pending[worker] = Some(start);
            }
            state.next = end;
        }
        Ok(start..end)
    }
    pub fn acknowledge(&self, worker: usize) -> Result<(), String> {
        let mut state = self.reservations.lock().unwrap();
        state.pending[worker] = None;
        let end = state
            .pending
            .iter()
            .filter_map(|&start| start)
            .min()
            .unwrap_or(state.next);
        self.acknowledged.store(end, Ordering::Release);
        Ok(())
    }
    pub fn delete_oldest(&self, count: u64) -> Range<u64> {
        let end = self.acknowledged.load(Ordering::Acquire);
        let mut start = self.floor.load(Ordering::Acquire);
        loop {
            let next = start.saturating_add(count).min(end);
            match self
                .floor
                .compare_exchange_weak(start, next, Ordering::AcqRel, Ordering::Acquire)
            {
                Ok(_) => return start..next,
                Err(actual) => start = actual,
            }
        }
    }
}

pub struct ValuePool {
    bytes: Vec<u8, System>,
    sizes: RangeInclusive<usize>,
}

impl ValuePool {
    pub fn new(seed: u64, sizes: RangeInclusive<usize>) -> Result<Self, String> {
        if *sizes.start() < 24 || sizes.is_empty() {
            return Err("value sizes must be at least 24 bytes and ascending".into());
        }
        let mut rng = RandomGenerator::new(seed);
        let mut bytes = Vec::with_capacity_in(64 * 1024 * 1024, System);
        bytes.resize(64 * 1024 * 1024, 0);
        for chunk in bytes.as_chunks_mut::<8>().0 {
            chunk.copy_from_slice(&rng.next_u64().to_le_bytes());
        }
        Ok(Self { bytes, sizes })
    }
    fn layout(&self, key: Key, version: u64) -> (usize, usize) {
        let hash = fnv(key.as_bytes()) ^ fnv(&version.to_le_bytes()).rotate_left(17);
        let len = *self.sizes.start() + (hash % ((*self.sizes.end() - *self.sizes.start() + 1) as u64)) as usize;
        (len, (hash.rotate_left(31) % self.bytes.len() as u64) as usize)
    }
    pub fn len(&self, key: Key, version: u64) -> usize {
        self.layout(key, version).0
    }
    pub fn fill(&self, key: Key, version: u64, output: &mut [u8]) -> Result<(), String> {
        let (len, mut offset) = self.layout(key, version);
        if output.len() != len {
            return Err("value buffer length mismatch".into());
        }
        output[..16].copy_from_slice(key.as_bytes());
        output[16..24].copy_from_slice(&version.to_be_bytes());
        let mut position = 24;
        while position < len {
            let take = (len - position).min(self.bytes.len() - offset);
            output[position..position + take].copy_from_slice(&self.bytes[offset..offset + take]);
            position += take;
            offset = 0;
        }
        Ok(())
    }
    /// The hex digit pairs of a version-0 document payload: the key, 8 zero bytes, then pool bytes.
    fn hex_pairs(&self, key: Key, offset: usize, len: usize) -> impl Iterator<Item = [u8; 2]> + '_ {
        const HEX: &[u8; 16] = b"0123456789abcdef";
        let header = key.into_bytes().into_iter().chain([0; 8]);
        let body = (0..).map(move |index| self.bytes[(offset + index) % self.bytes.len()]);
        header
            .chain(body)
            .take(len)
            .map(|byte| [HEX[(byte >> 4) as usize], HEX[(byte & 15) as usize]])
    }
    pub fn fill_hex(&self, key: Key, output: &mut [u8]) -> Result<(), String> {
        let (len, offset) = self.layout(key, 0);
        if output.len() != len * 2 {
            return Err("document payload length mismatch".into());
        }
        for (pair, expected) in output
            .as_chunks_mut::<2>()
            .0
            .iter_mut()
            .zip(self.hex_pairs(key, offset, len))
        {
            *pair = expected;
        }
        Ok(())
    }
    pub fn verify_hex(&self, key: Key, value: &str) -> Result<(), String> {
        let (len, offset) = self.layout(key, 0);
        if value.len() != len * 2 {
            return Err("document payload length mismatch".into());
        }
        if value
            .as_bytes()
            .as_chunks::<2>()
            .0
            .iter()
            .copied()
            .eq(self.hex_pairs(key, offset, len))
        {
            Ok(())
        } else {
            Err("document payload mismatch".into())
        }
    }
    pub fn verify(&self, key: Key, value: &[u8]) -> Result<u64, String> {
        if value.len() < 24 || value[..16] != *key.as_bytes() {
            return Err("value key header mismatch or truncated value".into());
        }
        let version = u64::from_be_bytes(value[16..24].try_into().unwrap());
        let (len, mut offset) = self.layout(key, version);
        if len != value.len() {
            return Err("value length mismatch".into());
        }
        let mut position = 24;
        while position < len {
            let take = (len - position).min(self.bytes.len() - offset);
            if value[position..position + take] != self.bytes[offset..offset + take] {
                return Err("value payload mismatch".into());
            }
            position += take;
            offset = 0;
        }
        Ok(version)
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn key_files_span_shards_decode_by_search_and_refuse_unsorted_keys() {
        let directory = tempfile::tempdir().unwrap();
        let write = |name: &str, keys: &[u64]| {
            let mut bytes = Vec::new();
            bytes.extend_from_slice(&(keys.len() as u32).to_le_bytes());
            bytes.extend_from_slice(&1u32.to_le_bytes());
            keys.iter().for_each(|key| bytes.extend_from_slice(&key.to_le_bytes()));
            std::fs::write(directory.path().join(name), bytes).unwrap();
        };
        write("keys.part_2.u64bin", &[30, 40]);
        write("keys.part_10.u64bin", &[50]);
        let keys = Keys::new(Some(&directory.path().join("keys.part_*.u64bin")), KeyType::U64).unwrap();
        assert_eq!(keys.capacity(), 3);
        assert_eq!(keys.encode(2), Key::from_u128(50));
        assert_eq!(keys.decode(Key::from_u128(40)), Some(1));
        assert_eq!(keys.decode(Key::from_u128(45)), None);
        write("keys.part_20.u64bin", &[10]);
        assert!(Keys::new(Some(&directory.path().join("keys.part_*.u64bin")), KeyType::U64).is_err());
    }
    #[test]
    fn reservations_publish_only_after_gaps_commit() {
        let keys = KeySpace::new(10);
        keys.workers(2);
        keys.reserve(0, 5).unwrap();
        keys.reserve(1, 7).unwrap();
        keys.acknowledge(1).unwrap();
        assert_eq!(keys.live(), 0..10);
        keys.acknowledge(0).unwrap();
        assert_eq!(keys.live(), 0..22);
        assert_eq!(keys.delete_oldest(30), 0..22);
        assert_eq!(keys.live(), 22..22);
    }
    #[test]
    fn concurrent_reservations_are_unique() {
        let keys = KeySpace::new(0);
        keys.workers(8);
        std::thread::scope(|scope| {
            for worker in 0..8 {
                let keys = &keys;
                scope.spawn(move || {
                    for _ in 0..1000 {
                        keys.reserve(worker, 3).unwrap();
                        keys.acknowledge(worker).unwrap();
                    }
                });
            }
        });
        assert_eq!(keys.live(), 0..24000);
    }
    #[test]
    fn verification_rejects_damage_and_wrong_keys() {
        let pool = ValuePool::new(42, 24..=1024).unwrap();
        let key = Key::from_u128(123);
        let mut value = Vec::with_capacity_in(pool.len(key, 7), System);
        value.resize(pool.len(key, 7), 0);
        pool.fill(key, 7, &mut value).unwrap();
        assert_eq!(pool.verify(key, &value).unwrap(), 7);
        assert!(pool.verify(Key::from_u128(124), &value).is_err());
        let end = value.len() - 1;
        value[end] ^= 1;
        assert!(pool.verify(key, &value).is_err());
        value.pop();
        assert!(pool.verify(key, &value).is_err());
    }
    #[test]
    fn zipf_preserves_double_precision_at_billion_key_scale() {
        let mut rng = RandomGenerator::new(42);
        let zeta = 26.46902820178302;
        let eta = zipf_eta(10_000_000_000, zeta);
        let expected = [
            8_999_346,
            1_560_521_264,
            115_271_083,
            1_751_185_404,
            3_808,
            1_918_126_200,
        ];
        for rank in expected {
            assert!(rng.zipf_rank(10_000_000_000, zeta, eta).abs_diff(rank) <= 1);
        }
    }

    #[test]
    fn seeded_distributions_cover_large_keys_and_latest_skews_recent() {
        let mut first = RandomGenerator::new(42);
        let mut second = RandomGenerator::new(42);
        let mut large = false;
        let mut recent = 0;
        for _ in 0..10000 {
            let key = first.sample(Distribution::Zipf, 0..1_000_000_000).unwrap();
            assert_eq!(Some(key), second.sample(Distribution::Zipf, 0..1_000_000_000));
            large |= key > 900_000_000;
        }
        for _ in 0..10000 {
            if first.sample(Distribution::Latest, 0..1000).unwrap() >= 900 {
                recent += 1;
            }
        }
        assert!(large);
        assert!(recent > 5000);
        assert_eq!(first.sample(Distribution::Uniform, 3..3), None);
    }
}
